import{_ as o,o as a,c as t,a2 as r}from"./chunks/framework.CgxQ0r6v.js";const p=JSON.parse('{"title":"0. Portada y Resumen Ejecutivo (Ejemplo Real)","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_I/Plantilla_Ejemplo/0_Portada_y_Resumen.md","filePath":"materias/Proyecto_Sociotecnologico_I/Plantilla_Ejemplo/0_Portada_y_Resumen.md"}'),n={name:"materias/Proyecto_Sociotecnologico_I/Plantilla_Ejemplo/0_Portada_y_Resumen.md"};function i(s,e,l,c,d,m){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="_0-portada-y-resumen-ejecutivo-ejemplo-real" tabindex="-1">0. Portada y Resumen Ejecutivo (Ejemplo Real) <a class="header-anchor" href="#_0-portada-y-resumen-ejecutivo-ejemplo-real" aria-label="Permalink to &quot;0. Portada y Resumen Ejecutivo (Ejemplo Real)&quot;">​</a></h1><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>Instrucciones de Uso:</strong> Este documento es un <em>Ejemplo Guiado</em>. Los textos que están entre corchetes <code>[como este]</code> indican las áreas que tú debes modificar con la información real de tu proyecto. El resto del texto es un ejemplo de redacción correcta, impersonal y académica.</p></div><hr><h2 id="📄-la-portada-institucional" tabindex="-1">📄 LA PORTADA INSTITUCIONAL <a class="header-anchor" href="#📄-la-portada-institucional" aria-label="Permalink to &quot;📄 LA PORTADA INSTITUCIONAL&quot;">​</a></h2><p>REPÚBLICA BOLIVARIANA DE VENEZUELA<br> MINISTERIO DEL PODER POPULAR PARA LA EDUCACIÓN UNIVERSITARIA<br> UNIVERSIDAD POLITÉCNICA TERRITORIAL DEL ESTADO TRUJILLO &quot;MARIO BRICEÑO IRAGORRY&quot;<br> PROGRAMA NACIONAL DE FORMACIÓN EN INFORMÁTICA (PNFI)<br><strong>UNIDAD DE PROYECTO SOCIO INTEGRADOR Y TECNOLÓGICO (UPSIT)</strong></p><p><br><br></p><p><strong>[TÍTULO DEL PROYECTO]</strong><br><em>Ejemplo: Soporte Técnico, Mantenimiento Preventivo y Alfabetización Tecnológica del Laboratorio de Computación en la U.E.N. &quot;Simón Bolívar&quot;, Municipio Valera, Estado Trujillo.</em></p><p><br><br></p><p><strong>Autores (Equipo Investigador):</strong><br> Pérez, Juan. C.I: 28.123.456<br> González, María. C.I: 29.654.321<br> López, Carlos. C.I: 30.987.654</p><p><strong>Tutor Técnico:</strong> Ing. José Hernández<br><strong>Tutor Académico:</strong> Lcda. Ana Martínez<br><strong>Trayecto:</strong> I</p><p><strong>Lugar y Fecha:</strong><br> Valera, Noviembre de 2026.</p><hr><h2 id="📝-el-resumen-ejecutivo" tabindex="-1">📝 EL RESUMEN EJECUTIVO <a class="header-anchor" href="#📝-el-resumen-ejecutivo" aria-label="Permalink to &quot;📝 EL RESUMEN EJECUTIVO&quot;">​</a></h2><p><em>El resumen es lo último que se escribe en el proyecto, pero es lo primero que lee el jurado. Debe contener máximo 300 palabras y resumir: el problema, el objetivo, la metodología y los resultados.</em></p><p><strong>RESUMEN</strong></p><p>El presente Proyecto Sociotecnológico, enmarcado en el Trayecto I del Programa Nacional de Formación en Informática (PNFI), se desarrolló en la <strong>[Unidad Educativa Nacional &quot;Simón Bolívar&quot;]</strong>, ubicada en <strong>[el municipio Valera, estado Trujillo]</strong>. Durante el diagnóstico participativo, se evidenció <strong>[una alta inoperatividad de los equipos de computación del laboratorio, limitando el acceso de los estudiantes a las Tecnologías de la Información y Comunicación (TIC)]</strong>. El objetivo general consistió en <strong>[ejecutar soporte técnico preventivo y correctivo para lograr la operatividad al 100% del laboratorio, así como la alfabetización del personal administrativo]</strong>. Metodológicamente, la investigación se apoyó en el <strong>[Enfoque del Marco Lógico (EML)]</strong>, utilizando técnicas como la observación directa y la entrevista estructurada. Entre los resultados más relevantes, se destaca <strong>[la recuperación de 15 estaciones de trabajo, la instalación del sistema operativo Canaima GNU/Linux, y la capacitación de 5 docentes en herramientas ofimáticas]</strong>. Se concluye que <strong>[la intervención técnica mejoró significativamente los procesos administrativos y educativos de la institución, cumpliendo con las normativas de la Ley de Infogobierno]</strong>.</p><p><strong>Descriptores (Palabras clave):</strong> <em>Soporte Técnico, Mantenimiento, Alfabetización Tecnológica, Marco Lógico, PNFI.</em></p>',17)])])}const E=o(n,[["render",i]]);export{p as __pageData,E as default};
